  "created_date" timestamptz not null default now(),
  "updated_date" timestamptz not null default now(),
  "created_by" text,
  "created_by_id" text,
  "is_sample" boolean not null default false,
  "_extra" jsonb not null default '{}'::jsonb,
  "register_id" text,
  "obligation_id" text,
  "template_origin_id" text,
  "title" text,
  "description" text,
  "category" text,
  "regulator" text,
  "owner" text,
  "frequency" text,
  "due_date" date,
  "priority" text,
  "status" text default 'Not Started',
  "register_status" text default 'active',
  "custom_fields" jsonb,
  "order_index" numeric default 0
);
comment on table public."compliance_obligations" is 'Base44 entity: ComplianceObligation';
comment on column public."compliance_obligations"."register_id" is 'REQUIRED — Parent ComplianceRegister ID';
comment on column public."compliance_obligations"."obligation_id" is 'Human-readable obligation ID, e.g. OBL-001';
comment on column public."compliance_obligations"."template_origin_id" is 'Stable identity of the template library item this obligation was applied from. Used to prevent adding the same template item to the same register twice.';
comment on column public."compliance_obligations"."title" is 'REQUIRED — Obligation title / name (required)';
comment on column public."compliance_obligations"."description" is 'Detailed description of the compliance obligation';
comment on column public."compliance_obligations"."category" is 'Compliance category value from register config';
comment on column public."compliance_obligations"."regulator" is 'Regulatory body or authority responsible for this obligation';
comment on column public."compliance_obligations"."owner" is 'Person or role responsible for the obligation';
comment on column public."compliance_obligations"."frequency" is 'How often this obligation recurs (Monthly, Quarterly, Annually, Ad Hoc, One-off)';
comment on column public."compliance_obligations"."due_date" is 'Obligation due date';
comment on column public."compliance_obligations"."priority" is 'Priority value from register config';
comment on column public."compliance_obligations"."status" is 'one of: Not Started | In Progress | Completed | On Hold | Cancelled — Obligation status';
comment on column public."compliance_obligations"."register_status" is 'one of: active | completed | archived — Tab placement state — controls which capsule tab (Open/Closed/Archived) the obligation appears under';
comment on column public."compliance_obligations"."custom_fields" is 'JSON map of custom column id → value';
create trigger "compliance_obligations_touch" before insert or update on public."compliance_obligations"
  for each row execute function public.b44_touch();
create index if not exists "compliance_obligations_created_date_idx" on public."compliance_obligations" (created_date desc);
create index if not exists "compliance_obligations_register_id_idx" on public."compliance_obligations" ("register_id");
create index if not exists "compliance_obligations_obligation_id_idx" on public."compliance_obligations" ("obligation_id");
create index if not exists "compliance_obligations_template_origin_id_idx" on public."compliance_obligations" ("template_origin_id");

-- ComplianceRegister
create table if not exists public."compliance_registers" (
  "id" text primary key default public.new_id(),
  "created_date" timestamptz not null default now(),
  "updated_date" timestamptz not null default now(),
  "created_by" text,
  "created_by_id" text,
  "is_sample" boolean not null default false,
  "_extra" jsonb not null default '{}'::jsonb,
  "title" text,
  "description" text,
  "compliance_period_type" text default 'Financial Year',
  "financial_year_start" date,
  "financial_year_end" date,
  "status" text default 'active',
  "config" jsonb
);
comment on table public."compliance_registers" is 'Base44 entity: ComplianceRegister';
comment on column public."compliance_registers"."title" is 'REQUIRED — Compliance calendar / register title, e.g. 2028-2029 Compliance Register';
comment on column public."compliance_registers"."description" is 'Optional description of the compliance register';
comment on column public."compliance_registers"."compliance_period_type" is 'one of: Financial Year | Calendar Year — Which yearly cycle this calendar covers — Financial Year (1 July – 30 June) or Calendar Year (1 Jan – 31 Dec)';
comment on column public."compliance_registers"."financial_year_start" is 'Start date of the compliance period this calendar covers (1 July for FY, 1 Jan for calendar year)';
comment on column public."compliance_registers"."financial_year_end" is 'End date of the compliance period this calendar covers (30 June for FY, 31 Dec for calendar year)';
comment on column public."compliance_registers"."status" is 'one of: active | archived — Register lifecycle status — controls which tab (Active/Archived) it appears under';
comment on column public."compliance_registers"."config" is 'Register-level configuration: field definitions, column order, etc.';
create trigger "compliance_registers_touch" before insert or update on public."compliance_registers"
  for each row execute function public.b44_touch();
create index if not exists "compliance_registers_created_date_idx" on public."compliance_registers" (created_date desc);

