-- ConflictOfInterest
create table if not exists public."conflicts_of_interest" (
  "id" text primary key default public.new_id(),
  "created_date" timestamptz not null default now(),
  "updated_date" timestamptz not null default now(),
  "created_by" text,
  "created_by_id" text,
  "is_sample" boolean not null default false,
  "_extra" jsonb not null default '{}'::jsonb,
  "register_id" text,
  "conflict_id" text,
  "member_user_id" text,
  "member_name" text,
  "title" text,
  "date_of_disclosure" date,
  "description" text,
  "committee_notified" text,
  "status" text default 'Active',
  "conflict_type" text,
  "review_frequency" text,
  "interval_value" numeric,
  "interval_unit" text,
  "last_review_date" date,
  "next_review_date" date,
  "risk_exposure" text,
  "approved_by" text,
  "approved_date" date,
  "custom_fields" jsonb,
  "order_index" numeric default 0
);
comment on table public."conflicts_of_interest" is 'Base44 entity: ConflictOfInterest';
comment on column public."conflicts_of_interest"."register_id" is 'Compliance Conflict of Interest Register ID. Empty for Board People conflicts.';
comment on column public."conflicts_of_interest"."conflict_id" is 'Human-readable conflict ID, e.g. COI-001 — auto-populated, editable, unique';
comment on column public."conflicts_of_interest"."member_user_id" is 'Board: optional linked BoardPerson user_id. Compliance: linked CoiPerson ID.';
comment on column public."conflicts_of_interest"."member_name" is 'Person''s display name — point-in-time snapshot';
comment on column public."conflicts_of_interest"."title" is 'Declaration title (Compliance register)';
comment on column public."conflicts_of_interest"."date_of_disclosure" is 'Date of declaration';
comment on column public."conflicts_of_interest"."description" is 'REQUIRED — Nature of interest';
comment on column public."conflicts_of_interest"."committee_notified" is 'one of: Yes | No | Not Required — Whether the committee was notified. Board: Yes/No. Compliance: Yes/Not Required.';
comment on column public."conflicts_of_interest"."status" is 'one of: Active | Archived — Conflict lifecycle status';
comment on column public."conflicts_of_interest"."conflict_type" is 'Conflict type: Perceived, Potential or Actual (empty when unset)';
comment on column public."conflicts_of_interest"."review_frequency" is 'Review frequency preset (Monthly, Quarterly, Biannually, Annually, Every, Ad Hoc)';
comment on column public."conflicts_of_interest"."interval_value" is 'Custom review interval value, used only when review_frequency is ''Every''';
comment on column public."conflicts_of_interest"."interval_unit" is 'one of: Months | Years — Custom review interval unit, used only when review_frequency is ''Every''';
comment on column public."conflicts_of_interest"."last_review_date" is 'The date the conflict was last reviewed';
comment on column public."conflicts_of_interest"."next_review_date" is 'The date the conflict is next due for review';
comment on column public."conflicts_of_interest"."risk_exposure" is 'one of: High | Medium | Low — Risk exposure level';
comment on column public."conflicts_of_interest"."approved_by" is 'Free-text name of the person who approved';
comment on column public."conflicts_of_interest"."approved_date" is 'Date the declaration was approved';
comment on column public."conflicts_of_interest"."custom_fields" is 'JSON map of custom field id → value for configured fields';
create trigger "conflicts_of_interest_touch" before insert or update on public."conflicts_of_interest"
  for each row execute function public.b44_touch();
create index if not exists "conflicts_of_interest_created_date_idx" on public."conflicts_of_interest" (created_date desc);
create index if not exists "conflicts_of_interest_register_id_idx" on public."conflicts_of_interest" ("register_id");
create index if not exists "conflicts_of_interest_conflict_id_idx" on public."conflicts_of_interest" ("conflict_id");
create index if not exists "conflicts_of_interest_member_user_id_idx" on public."conflicts_of_interest" ("member_user_id");

