-- Contract
create table if not exists public."contracts" (
  "id" text primary key default public.new_id(),
  "created_date" timestamptz not null default now(),
  "updated_date" timestamptz not null default now(),
  "created_by" text,
  "created_by_id" text,
  "is_sample" boolean not null default false,
  "_extra" jsonb not null default '{}'::jsonb,
  "register_id" text,
  "contract_code" text,
  "title" text,
  "description" text,
  "contract_type" text,
  "has_financial_value" boolean default false,
  "value" numeric,
  "payment_schedule" jsonb,
  "start_date" date,
  "expiry_date" date,
  "review_frequency" text,
  "interval_value" numeric,
  "interval_unit" text,
  "last_review_date" date,
  "next_review_date" date,
  "owner" text,
  "manager" text,
  "business_division" text,
  "status" text default 'Active',
  "party_name" text,
  "party_contact" text,
  "party_email" text,
  "party_phone" text,
  "additional_parties" jsonb,
  "custom_fields" jsonb
);
comment on table public."contracts" is 'Base44 entity: Contract';
comment on column public."contracts"."register_id" is 'REQUIRED — Parent ComplianceManagedRegister ID (Contract Register)';
comment on column public."contracts"."contract_code" is 'REQUIRED — Contract reference, e.g. CON-001 (unique within the register)';
comment on column public."contracts"."title" is 'REQUIRED';
comment on column public."contracts"."contract_type" is 'From register config.contract_types';
comment on column public."contracts"."value" is 'Contract value';
comment on column public."contracts"."payment_schedule" is 'Payment schedule rows stored with the contract';
comment on column public."contracts"."review_frequency" is 'one of: Monthly | Quarterly | Biannually | Annually | Every | Ad Hoc';
comment on column public."contracts"."interval_value" is 'Custom interval, used only when review_frequency is ''Every''';
comment on column public."contracts"."interval_unit" is 'one of: Months | Years';
comment on column public."contracts"."next_review_date" is 'Auto-calculated from frequency and last review date';
comment on column public."contracts"."owner" is 'Contract owner';
comment on column public."contracts"."manager" is 'Contract manager';
comment on column public."contracts"."business_division" is 'The business area the contract relates to';
comment on column public."contracts"."status" is 'REQUIRED — one of: Active | Archived';
comment on column public."contracts"."party_name" is 'Counterparty name';
comment on column public."contracts"."party_contact" is 'Counterparty contact person';
comment on column public."contracts"."additional_parties" is 'Up to three additional parties to the contract';
comment on column public."contracts"."custom_fields" is 'Values for config.custom_columns keyed by column id';
create trigger "contracts_touch" before insert or update on public."contracts"
  for each row execute function public.b44_touch();
create index if not exists "contracts_created_date_idx" on public."contracts" (created_date desc);
create index if not exists "contracts_register_id_idx" on public."contracts" ("register_id");

