-- Conversation
create table if not exists public."conversations" (
  "id" text primary key default public.new_id(),
  "created_date" timestamptz not null default now(),
  "updated_date" timestamptz not null default now(),
  "created_by" text,
  "created_by_id" text,
  "is_sample" boolean not null default false,
  "_extra" jsonb not null default '{}'::jsonb,
  "type" text,
  "name" text,
  "color" text,
  "member_ids" jsonb,
  "admin_ids" jsonb,
  "hidden_by" jsonb,
  "direct_key" text,
  "last_message_text" text,
  "last_message_sender_id" text,
  "last_message_at" text,
  "poll_activity_at" text,
  "pin_activity_at" text,
  "file_activity_at" text,
  "file_removed_message_id" text,
  "read_activity_at" text
);
comment on table public."conversations" is 'Base44 entity: Conversation';
comment on column public."conversations"."type" is 'REQUIRED — one of: direct | group — direct = two team members, group = a named group chat';
comment on column public."conversations"."name" is 'Group name (group conversations only)';
comment on column public."conversations"."color" is 'one of: orange | yellow | green | teal | lavender — Group tile colour key from the folder palette (group conversations only)';
comment on column public."conversations"."member_ids" is 'REQUIRED — User IDs of the participants. Only these users can read the conversation.';
comment on column public."conversations"."admin_ids" is 'User IDs of the group''s admins (group conversations only). Only admins can rename, recolour, add or remove members, assign admins, or delete the group. A group always keeps at least one admin; set by the conversations function.';
comment on column public."conversations"."hidden_by" is 'User IDs of members who deleted this direct conversation from their own list. Cleared when a new message or poll is posted; once every member has hidden it, the conversation is removed. Set by the conversations function.';
comment on column public."conversations"."direct_key" is 'Sorted pair of user IDs for a direct conversation, so each pair shares one conversation';
comment on column public."conversations"."last_message_text" is 'Short preview of the latest message';
comment on column public."conversations"."last_message_sender_id" is 'User ID of the latest message''s sender';
comment on column public."conversations"."last_message_at" is 'ISO timestamp of the latest activity; conversations are listed by it';
comment on column public."conversations"."poll_activity_at" is 'ISO timestamp of the latest poll vote or closure; tells members'' open threads to refresh';
comment on column public."conversations"."pin_activity_at" is 'ISO timestamp of the latest pin or unpin; tells members'' open threads to refresh their pinned bar';
comment on column public."conversations"."file_activity_at" is 'ISO timestamp of the latest shared-file deletion; tells members'' open threads to drop that file';
comment on column public."conversations"."file_removed_message_id" is 'ConversationMessage ID whose file was deleted most recently; set together with file_activity_at by the conversations function';
comment on column public."conversations"."read_activity_at" is 'ISO timestamp of the latest time a member caught up on the conversation; tells members'' lists to refresh unread counts and Read receipts';
create trigger "conversations_touch" before insert or update on public."conversations"
  for each row execute function public.b44_touch();
create index if not exists "conversations_created_date_idx" on public."conversations" (created_date desc);
create index if not exists "conversations_member_ids_gin" on public."conversations" using gin ("member_ids");
create index if not exists "conversations_admin_ids_gin" on public."conversations" using gin ("admin_ids");
create index if not exists "conversations_last_message_sender_id_idx" on public."conversations" ("last_message_sender_id");
create index if not exists "conversations_file_removed_message_id_idx" on public."conversations" ("file_removed_message_id");

-- ConversationMessage
create table if not exists public."conversation_messages" (
  "id" text primary key default public.new_id(),
