);
comment on table public."decisions" is 'Base44 entity: Decision';
comment on column public."decisions"."register_id" is 'REQUIRED — Parent DecisionRegister ID';
comment on column public."decisions"."decision_type" is 'one of: Decision | Resolution — Decision = agreed by consensus or noted; Resolution = a formal motion, moved and voted on';
comment on column public."decisions"."title" is 'REQUIRED — Decision title shown in the register table';
comment on column public."decisions"."minuted_text" is 'The decision as it appears in the minutes';
comment on column public."decisions"."meeting_id" is 'Optional linked Meeting ID. The meeting''s title and date are always read from that Meeting record, never copied onto the decision.';
comment on column public."decisions"."agenda_item" is 'Agenda item reference, e.g. 5.1';
comment on column public."decisions"."outcome" is 'Agreed, Approved, Endorsed, Noted or Declined; empty when not recorded';
comment on column public."decisions"."decision_date" is 'Date of the decision (yyyy-mm-dd). Filled from the linked meeting''s date and editable; empty when not recorded.';
comment on column public."decisions"."mover" is 'Person who moved the motion (resolutions only)';
comment on column public."decisions"."seconder" is 'Person who seconded the motion (resolutions only)';
comment on column public."decisions"."votes_for" is 'Votes in favour (resolutions only)';
comment on column public."decisions"."votes_against" is 'Votes against (resolutions only)';
comment on column public."decisions"."votes_abstained" is 'Abstentions (resolutions only)';
comment on column public."decisions"."disposition" is 'one of: No | Supersedes | Rescinds — Answer to ''Replaces an earlier decision?''. Sets the tab and status: No = Current, Supersedes = Superseded, Rescinds = Rescinded.';
comment on column public."decisions"."earlier_decision_id" is 'Decision ID of the earlier decision this one supersedes or rescinds; empty when disposition is No';
create trigger "decisions_touch" before insert or update on public."decisions"
  for each row execute function public.b44_touch();
