  "register_id" text,
  "action_id" text,
  "meeting_id" text,
  "minute_ref" text,
  "title" text,
  "description" text,
  "raised_by" text,
  "assigned_to" text,
  "due_date" date,
  "priority" text,
  "status" text default 'Open',
  "register_status" text default 'active',
  "custom_fields" jsonb,
  "order_index" numeric default 0
);
comment on table public."meeting_action_items" is 'Base44 entity: MeetingActionItem';
comment on column public."meeting_action_items"."register_id" is 'REQUIRED — Parent MeetingActionRegister ID';
comment on column public."meeting_action_items"."action_id" is 'Human-readable action ID, e.g. ACT-001';
comment on column public."meeting_action_items"."meeting_id" is 'Optional linked Meeting ID. The meeting''s title, committee and date are always read from that Meeting record, never copied onto the action.';
comment on column public."meeting_action_items"."minute_ref" is 'Minute or agenda item reference, e.g. Item 5.2';
comment on column public."meeting_action_items"."title" is 'Action title shown in the register table (required in the form)';
comment on column public."meeting_action_items"."description" is 'Optional action description, shown in the view/edit pane only';
comment on column public."meeting_action_items"."raised_by" is 'Person who raised the action';
comment on column public."meeting_action_items"."assigned_to" is 'Person or role assigned to action';
comment on column public."meeting_action_items"."due_date" is 'Action due date';
comment on column public."meeting_action_items"."priority" is 'Priority value from register config';
comment on column public."meeting_action_items"."status" is 'one of: Open | In Progress | Completed | Deferred | Cancelled — Lifecycle status. Overdue is never stored — it is a computed display flag (past due date, not Completed/Cancelled/On Hold, and not on the Closed tab) derived by isOverdue() against the shared org clock.';
comment on column public."meeting_action_items"."register_status" is 'one of: active | completed — Tab placement state — controls which capsule tab (Open/Closed) the action appears under. Archiving happens at the register level (MeetingActionRegister.status), never per action, so every action always belongs to a visible tab.';
comment on column public."meeting_action_items"."custom_fields" is 'JSON map of custom column id → value';
create trigger "meeting_action_items_touch" before insert or update on public."meeting_action_items"
  for each row execute function public.b44_touch();
create index if not exists "meeting_action_items_created_date_idx" on public."meeting_action_items" (created_date desc);
create index if not exists "meeting_action_items_register_id_idx" on public."meeting_action_items" ("register_id");
create index if not exists "meeting_action_items_action_id_idx" on public."meeting_action_items" ("action_id");
create index if not exists "meeting_action_items_meeting_id_idx" on public."meeting_action_items" ("meeting_id");

