  "first_name" text,
  "last_name" text,
  "email" text,
  "phone" text,
  "organisation" text,
  "street_address" text,
  "suburb" text,
  "state" text,
  "postal_code" text,
  "membership_structure_id" text,
  "membership_structure_name" text,
  "membership_tier_id" text,
  "membership_tier_name" text,
  "payment_method" text,
  "online_payment_type" text,
  "payment_status" text,
  "status" text default 'active',
  "tags" jsonb,
  "start_date" date,
  "expiration_date" date,
  "last_renewal_reminder_date" date,
  "notes" text,
  "custom_fields" jsonb
);
comment on table public."members" is 'Base44 entity: Member';
comment on column public."members"."first_name" is 'REQUIRED — Member first name';
comment on column public."members"."last_name" is 'Member last name (optional)';
comment on column public."members"."email" is 'Member email address';
comment on column public."members"."phone" is 'Member contact number';
comment on column public."members"."organisation" is 'Member organisation or company name';
comment on column public."members"."street_address" is 'Member street address';
comment on column public."members"."suburb" is 'Member suburb';
comment on column public."members"."state" is 'Member state';
comment on column public."members"."postal_code" is 'Member postal code';
comment on column public."members"."membership_structure_id" is 'Linked MembershipStructure ID';
comment on column public."members"."membership_structure_name" is 'Cached membership structure name for display';
comment on column public."members"."membership_tier_id" is 'Selected tier id within the membership structure (when the plan has tiers)';
comment on column public."members"."membership_tier_name" is 'Cached selected tier name for display';
comment on column public."members"."payment_method" is 'one of: Cash | Bank Transfer | Online Payment | Invoice — Payment method the member selected on the application form (editable by admins)';
comment on column public."members"."online_payment_type" is 'one of: one_time | recurrent — When payment_method is Online Payment: whether the member paid via a one-time payment or a recurrent (auto-rebilling) subscription';
comment on column public."members"."payment_status" is 'one of: Paid | Pending | Overdue — Payment status, manually verified and set by admins. ''Pending'' means payment is expected but not yet received — entirely separate from the membership ''status'' field''s lowercase ''pending'' (which is an approval state).';
comment on column public."members"."status" is 'one of: active | pending | expired | archived — Membership status. Set manually by admins, and automatically flipped to ''expired'' by the nightly expiry sweep once the plan''s expiration date plus grace period has passed and the plan''s ''After Grace Period'' is ''Mark as expired''. ''archived'' hides the member from the active tabs but retains the record until permanently deleted.';
comment on column public."members"."tags" is 'Tag names applied to this member';
comment on column public."members"."start_date" is 'Membership start date';
comment on column public."members"."expiration_date" is 'Membership expiration date (empty for lifetime)';
comment on column public."members"."last_renewal_reminder_date" is 'Date the last pre-expiry renewal reminder email was sent. Used by the nightly expiry sweep to send at most one reminder per expiry cycle.';
comment on column public."members"."notes" is 'Free-form notes about the member';
comment on column public."members"."custom_fields" is 'Custom field values keyed by field ID';
create trigger "members_touch" before insert or update on public."members"
  for each row execute function public.b44_touch();
create index if not exists "members_created_date_idx" on public."members" (created_date desc);
create index if not exists "members_membership_structure_id_idx" on public."members" ("membership_structure_id");
create index if not exists "members_membership_tier_id_idx" on public."members" ("membership_tier_id");

