comment on table public."membership_form_configs" is 'Base44 entity: MembershipFormConfig';
comment on column public."membership_form_configs"."slug" is 'REQUIRED — Stable identifier used in the public form URL. Defaults to ''default'' for the single primary form.';
comment on column public."membership_form_configs"."organisation_name" is 'Organisation name displayed on the public membership page';
comment on column public."membership_form_configs"."title" is 'Public form heading / membership page title';
comment on column public."membership_form_configs"."description" is 'Intro text shown under the form heading';
comment on column public."membership_form_configs"."support_email" is 'Support email displayed on the membership page for enquiries';
comment on column public."membership_form_configs"."social_links" is 'Optional social/website links shown on the public membership page';
comment on column public."membership_form_configs"."banner_url" is 'URL of the banner image shown at the top of the public form';
comment on column public."membership_form_configs"."success_message" is 'Message shown after a successful submission';
comment on column public."membership_form_configs"."selected_structure_ids" is 'MembershipStructure IDs exposed on this form';
comment on column public."membership_form_configs"."structure_rules" is 'Optional conditional visibility rules for membership structures. A structure listed here is only shown on the form when its condition group passes. Structures without an entry are always visible.';
comment on column public."membership_form_configs"."field_layout" is 'Ordered list of fields rendered on the form';
comment on column public."membership_form_configs"."status" is 'one of: active | disabled — Whether the public form accepts submissions';
