-- MembershipStructure
create table if not exists public."membership_structures" (
  "id" text primary key default public.new_id(),
  "created_date" timestamptz not null default now(),
  "updated_date" timestamptz not null default now(),
  "created_by" text,
  "created_by_id" text,
  "is_sample" boolean not null default false,
  "_extra" jsonb not null default '{}'::jsonb,
  "name" text,
  "membership_type" text default 'Individual',
  "description" text,
  "plan_content_sections" jsonb,
  "has_tiers" boolean default false,
  "tier_fees_differ" boolean default false,
  "tiers" jsonb,
  "price" numeric default 0,
  "fee_type" text default 'Free',
  "fee_amount" numeric default 0,
  "payment_methods" jsonb,
  "payment_method" text,
  "payment_link" text,
  "online_payment_type" text default 'one_time',
  "one_time_payment_link" text,
  "recurrent_payment_link" text,
  "bank_account_name" text,
  "bank_bsb" text,
  "bank_account_number" text,
  "bank_payment_reference" text,
  "show_pay_id" boolean default false,
  "pay_id" text,
  "stripe_product_id" text,
  "stripe_product_name" text,
  "duration_months" numeric default 12,
  "is_lifetime" boolean default false,
  "renewal_period" text default 'Annually',
  "renewal_interval_value" numeric default 1,
  "renewal_interval_unit" text default 'Years',
  "renewal_calculation" text default 'Based on date joined',
  "renewal_expiration_type" text default 'Calculated by date joined',
  "specific_expiration_day" numeric,
  "specific_expiration_month" numeric,
  "grace_period_days" numeric default 0,
  "after_grace_period" text default 'Mark as expired',
  "admin_approval_required" boolean default false,
  "deactivate_expired_memberships" boolean default false,
  "welcome_email_enabled" boolean default false,
  "renewal_reminder_enabled" boolean default false,
  "expiry_reminder_enabled" boolean default false,
  "is_system_default" boolean default false,
  "status" text default 'active',
  "application_fields" jsonb
);
comment on table public."membership_structures" is 'Base44 entity: MembershipStructure';
comment on column public."membership_structures"."name" is 'REQUIRED — Structure name, e.g. Annual Membership';
comment on column public."membership_structures"."membership_type" is 'one of: Individual | Group | Organisation — Deprecated. Who the membership structure applies to. No longer configured in the plan wizard.';
comment on column public."membership_structures"."description" is 'Optional description of the structure, displayed to new members on signup';
comment on column public."membership_structures"."plan_content_sections" is 'Additional customisable content sections (e.g. Membership Rights, Membership Benefits) displayed to new members on signup';
comment on column public."membership_structures"."has_tiers" is 'Whether this plan has multiple categories/tiers (e.g. Individual and Organisation)';
comment on column public."membership_structures"."tier_fees_differ" is 'Whether each category/tier has a different membership fee';
comment on column public."membership_structures"."tiers" is 'Configured categories/tiers for this plan';
comment on column public."membership_structures"."price" is 'Membership price';
comment on column public."membership_structures"."fee_type" is 'one of: Free | Fixed | Tiered | Custom | No Membership Fee — How this plan is priced. Free = no fee, Fixed = single fee, Tiered = per-tier fees, Custom = manual amount. ''No Membership Fee'' retained for legacy records.';
comment on column public."membership_structures"."fee_amount" is 'Fixed/custom membership fee amount (used when fee_type is Fixed or Custom)';
comment on column public."membership_structures"."payment_methods" is 'Accepted payment methods shown to members during registration';
comment on column public."membership_structures"."payment_method" is 'one of: Cash | Bank Transfer | Payment Link — Deprecated single payment method. Superseded by payment_methods array.';
comment on column public."membership_structures"."payment_link" is 'External online payment link URL. Treated as the one-time payment link for backward compatibility when one_time_payment_link is not set.';
comment on column public."membership_structures"."online_payment_type" is 'one of: one_time | both — For Online Payment: whether this plan accepts only one-time membership payments, or both one-time and recurrent (auto-rebilling subscription) payments.';
comment on column public."membership_structures"."one_time_payment_link" is 'Online payment link for a one-time (non-recurring) membership payment';
comment on column public."membership_structures"."recurrent_payment_link" is 'Online payment link for a recurrent (auto-rebilling subscription) membership payment';
comment on column public."membership_structures"."bank_account_name" is 'Bank account name (shown to members when Bank Transfer is accepted)';
comment on column public."membership_structures"."bank_bsb" is 'Bank BSB number (shown to members when Bank Transfer is accepted)';
comment on column public."membership_structures"."bank_account_number" is 'Bank account number (shown to members when Bank Transfer is accepted)';
comment on column public."membership_structures"."bank_payment_reference" is 'Optional payment reference instructions for Bank Transfer';
comment on column public."membership_structures"."show_pay_id" is 'Whether to show PayID details instead of / in addition to BSB & account number for Bank Transfer';
comment on column public."membership_structures"."pay_id" is 'PayID (email or phone) shown to members for bank transfer payment';
comment on column public."membership_structures"."stripe_product_id" is 'Linked Stripe product ID for the membership fee';
comment on column public."membership_structures"."stripe_product_name" is 'Cached Stripe product name for display';
comment on column public."membership_structures"."duration_months" is 'Duration in months used to auto-calculate expiration date (ignored when is_lifetime is true). Derived from the renewal period — for ''Every'' it is renewal_interval_value x (12 when the unit is Years).';
comment on column public."membership_structures"."is_lifetime" is 'When true, membership never expires and duration is ignored';
comment on column public."membership_structures"."renewal_period" is 'one of: One-off | Annually | Lifetime (No Expiration) | Every — Renewal period. One-off = single fixed term, Annually = yearly, Lifetime = never expires, Every = custom cadence set by renewal_interval_value/renewal_interval_unit.';
comment on column public."membership_structures"."renewal_interval_value" is 'Custom renewal interval value, used when renewal_period is ''Every'' (e.g. 3 for a three-year renewal)';
comment on column public."membership_structures"."renewal_interval_unit" is 'one of: Months | Years — Custom renewal interval unit, used when renewal_period is ''Every''';
comment on column public."membership_structures"."renewal_calculation" is 'one of: Based on date joined | Fixed renewal date | Financial year cycle | Calendar year cycle — How the renewal/expiration date is calculated';
comment on column public."membership_structures"."renewal_expiration_type" is 'one of: Calculated by date joined | On Specific Date — Deprecated. Superseded by renewal_calculation.';
comment on column public."membership_structures"."specific_expiration_day" is 'Day of month (1-31) for the fixed renewal date';
comment on column public."membership_structures"."specific_expiration_month" is 'Month (1-12) for the fixed renewal date';
comment on column public."membership_structures"."grace_period_days" is 'Grace period in days after expiry before action is taken (0, 14, 30, 60 or 90)';
comment on column public."membership_structures"."after_grace_period" is 'one of: Mark as expired | Keep active until admin review — What happens once the grace period ends';
comment on column public."membership_structures"."admin_approval_required" is 'When true, new members on this structure are saved as ''pending'' and must be manually activated by an admin';
comment on column public."membership_structures"."deactivate_expired_memberships" is 'When true, members on this structure are automatically set to ''expired'' once their renewal/expiration date passes';
comment on column public."membership_structures"."welcome_email_enabled" is 'Automatically send welcome emails to new members';
comment on column public."membership_structures"."renewal_reminder_enabled" is 'Automatically notify members before membership expiration';
comment on column public."membership_structures"."expiry_reminder_enabled" is 'Automatically notify members after membership expires';
comment on column public."membership_structures"."is_system_default" is 'When true, this is a seeded default structure and cannot be deleted';
comment on column public."membership_structures"."status" is 'one of: active | archived — Structure lifecycle status';
comment on column public."membership_structures"."application_fields" is 'Google-Forms-style application questions collected when this plan is selected. Each question may optionally map to a member profile field; unmapped answers are stored only in the submission history.';
create trigger "membership_structures_touch" before insert or update on public."membership_structures"
  for each row execute function public.b44_touch();
create index if not exists "membership_structures_created_date_idx" on public."membership_structures" (created_date desc);
create index if not exists "membership_structures_pay_id_idx" on public."membership_structures" ("pay_id");
create index if not exists "membership_structures_stripe_product_id_idx" on public."membership_structures" ("stripe_product_id");

