  "_extra" jsonb not null default '{}'::jsonb,
  "title" text,
  "description" text,
  "document_type" text,
  "category" text,
  "parent_id" text,
  "owner" text,
  "approved_by" text,
  "approved_date" date,
  "effective_date" date,
  "classification" text,
  "stage" text default 'Draft',
  "status" text default 'active',
  "review_with_parent" boolean default false,
  "review_frequency" text,
  "interval_value" numeric,
  "interval_unit" text,
  "last_review_date" date,
  "next_review_date" date,
  "current_version_id" text,
  "primary_file_uri" text,
  "primary_file_name" text,
  "primary_display_title" text,
  "custom_fields" jsonb,
  "content_sections" jsonb
);
comment on table public."policy_documents" is 'Base44 entity: PolicyDocument';
comment on column public."policy_documents"."title" is 'REQUIRED';
comment on column public."policy_documents"."document_type" is 'REQUIRED — From AppConfig policy_document_types';
comment on column public."policy_documents"."category" is 'REQUIRED — From AppConfig policy_categories; inherited from parent when linked';
comment on column public."policy_documents"."parent_id" is 'Parent Policy document ID (one level only)';
comment on column public."policy_documents"."effective_date" is 'The date the policy takes effect';
comment on column public."policy_documents"."classification" is 'one of: Public | Internal | Restricted';
comment on column public."policy_documents"."stage" is 'one of: Draft | Under Review | Approved | Withdrawn | Superseded';
comment on column public."policy_documents"."status" is 'REQUIRED — one of: active | archived';
comment on column public."policy_documents"."review_with_parent" is 'Linked document shares the parent''s review schedule';
comment on column public."policy_documents"."review_frequency" is 'one of: Monthly | Quarterly | Biannually | Annually | Every | Ad Hoc';
comment on column public."policy_documents"."interval_unit" is 'one of: Months | Years';
comment on column public."policy_documents"."current_version_id" is 'The single Current PolicyVersion. Set only by the policyVersions function together with the primary file fields, in one write.';
comment on column public."policy_documents"."primary_file_uri" is 'Private file URI of the Current version''s document (PDF or Word)';
comment on column public."policy_documents"."primary_file_name" is 'Original filename of the Current version''s document';
comment on column public."policy_documents"."primary_display_title" is 'Display title of the Current version''s document';
comment on column public."policy_documents"."custom_fields" is 'Values for AppConfig policy custom_columns keyed by column id';
comment on column public."policy_documents"."content_sections" is 'Readable text of the primary file, extracted once for search and the assistant';
