  "date_raised" date,
  "raised_by" text,
  "title" text,
  "description" text,
  "category" text,
  "risk_appetite" text,
  "owner" text,
  "cause" text,
  "impact" text,
  "inherent_likelihood" numeric,
  "inherent_consequence" numeric,
  "inherent_rating" text,
  "existing_controls" jsonb,
  "residual_likelihood" numeric,
  "residual_consequence" numeric,
  "residual_rating" text,
  "treatment_action" text,
  "treatment_plan" jsonb,
  "monitoring_method" text,
  "progress_notes" text,
  "review_frequency" text,
  "last_reviewed_date" date,
  "next_review_date" date,
  "review_log" jsonb,
  "rating_history" jsonb,
  "status" text default 'Active',
