  "version" numeric default 0
);
comment on table public."risks" is 'Base44 entity: Risk';
comment on column public."risks"."risk_id" is 'Human-readable risk ID, e.g. RISK-001 — assigned and kept unique (case-insensitive) by the createRisk / saveRisk functions';
comment on column public."risks"."date_raised" is 'Date the risk was first raised';
comment on column public."risks"."raised_by" is 'Name of the person who raised the risk';
comment on column public."risks"."title" is 'REQUIRED — Risk title';
comment on column public."risks"."description" is 'Detailed description of the risk';
comment on column public."risks"."category" is 'Risk category';
comment on column public."risks"."risk_appetite" is 'one of: Within Appetite | Outside Appetite — Whether the risk is within or outside the organisation''s risk appetite';
comment on column public."risks"."owner" is 'REQUIRED — Assigned risk owner';
comment on column public."risks"."cause" is 'Potential causes of the event occurring';
comment on column public."risks"."impact" is 'Main impact of the risk event';
comment on column public."risks"."inherent_likelihood" is 'Inherent (pre-mitigation) likelihood score 1-5';
comment on column public."risks"."inherent_consequence" is 'Inherent (pre-mitigation) consequence score 1-5';
comment on column public."risks"."inherent_rating" is 'Inherent (pre-mitigation) risk rating band — auto-calculated';
comment on column public."risks"."existing_controls" is 'Existing controls already in place to prevent, detect, or respond to the risk';
comment on column public."risks"."residual_likelihood" is 'Residual (post-mitigation) likelihood score 1-5';
comment on column public."risks"."residual_consequence" is 'Residual (post-mitigation) consequence score 1-5';
comment on column public."risks"."residual_rating" is 'Residual (post-mitigation) risk rating band — auto-calculated';
comment on column public."risks"."treatment_action" is 'Risk treatment strategy: Avoid (Terminate), Reduce (Mitigate), Transfer (Share), or Accept (Tolerate)';
comment on column public."risks"."treatment_plan" is 'List of treatment action plan items';
comment on column public."risks"."monitoring_method" is 'How the risk treatment is monitored (e.g. KPI tracking, audit, periodic review)';
comment on column public."risks"."progress_notes" is 'Progress and compliance reporting notes / status updates';
comment on column public."risks"."review_frequency" is 'How often the risk is reviewed (Monthly, Quarterly, Biannually, Annually, Ad Hoc)';
comment on column public."risks"."last_reviewed_date" is 'Date the risk was last reviewed';
comment on column public."risks"."next_review_date" is 'Date the risk is next due for review';
