  "updated_date" timestamptz not null default now(),
  "created_by" text,
  "created_by_id" text,
  "is_sample" boolean not null default false,
  "_extra" jsonb not null default '{}'::jsonb,
  "title" text,
  "start_year" numeric,
  "end_year" numeric,
  "description" text,
  "vision" text,
  "mission" text,
  "values" jsonb,
  "guiding_principles" jsonb,
  "owner" text,
  "color" text,
  "level_field_config" jsonb,
  "strategy_layers" jsonb,
  "status" text default 'Active'
);
comment on table public."strategies" is 'Base44 entity: Strategy';
comment on column public."strategies"."title" is 'REQUIRED — The name of the strategy (e.g. 5 Year Strategic Plan 2025-30)';
comment on column public."strategies"."start_year" is 'First year of the strategy period (e.g. 2025)';
comment on column public."strategies"."end_year" is 'Last year of the strategy period (e.g. 2030)';
comment on column public."strategies"."description" is 'Legacy strategy summary. Superseded by vision/mission/values.';
comment on column public."strategies"."vision" is 'The strategy''s vision statement';
comment on column public."strategies"."mission" is 'The strategy''s mission statement (optional)';
comment on column public."strategies"."values" is 'Organisational values shown as coloured labels';
comment on column public."strategies"."guiding_principles" is 'Optional guiding principles for the strategy, shown as muted pills';
comment on column public."strategies"."owner" is 'Department, Division, or person responsible (e.g. CEO, Department of International Trade)';
comment on column public."strategies"."color" is 'Card colour key (same options as Program cards)';
comment on column public."strategies"."level_field_config" is 'Per-layer table field configuration from the Strategy Customiser, keyed ''level{slot}'' where slot is the layer''s numeric storage slot. Each entry holds { priority_visible: boolean, custom: [{ id, title, type, config }] }. Priority is a locked system field (options never editable) and is absent on the Priorities layer.';
comment on column public."strategies"."strategy_layers" is 'Ordered hierarchy layers for this strategy. Array order is the hierarchy order. Vision and Strategic Theme are always the first two layers and cannot be reordered.';
comment on column public."strategies"."status" is 'one of: Draft | Active | Archived — Strategy lifecycle status';
create trigger "strategies_touch" before insert or update on public."strategies"
  for each row execute function public.b44_touch();
create index if not exists "strategies_created_date_idx" on public."strategies" (created_date desc);

