  "title" text,
  "content" text,
  "owner" text,
  "owners" jsonb,
  "executive_sponsor" text,
  "target_year" text,
  "start_date" date,
  "end_date" date,
  "due_date" date,
  "progress" numeric,
  "priority" text,
  "custom_fields" jsonb,
  "tracking_config" jsonb,
