  "order_index" numeric default 0
);
comment on table public."strategy_blocks" is 'Base44 entity: StrategyBlock';
comment on column public."strategy_blocks"."strategy_id" is 'REQUIRED — Parent Strategy ID this block belongs to';
comment on column public."strategy_blocks"."parent_id" is 'ID of the parent StrategyBlock one level above (empty for top-level blocks)';
comment on column public."strategy_blocks"."level2_id" is 'Linked StrategyLevel2 pillar ID (used by Priorities items to assign a Focus Area label)';
comment on column public."strategy_blocks"."level" is 'REQUIRED — Numeric storage slot of the hierarchy layer this block belongs to (matches a layer''s level in the parent Strategy''s strategy_layers). An identifier only: it does not imply hierarchy order, and the user-facing name always comes from the layer.';
comment on column public."strategy_blocks"."custom_id" is 'Human-readable, user-editable record ID unique within the strategy, e.g. MEA-001';
comment on column public."strategy_blocks"."title" is 'REQUIRED — Block title / name';
comment on column public."strategy_blocks"."content" is 'Description / details for this block';
comment on column public."strategy_blocks"."owner" is 'Legacy single owner. Kept in sync with the first entry of owners for backward compatibility.';
comment on column public."strategy_blocks"."owners" is 'People or teams responsible for this item. Supports multiple owners.';
comment on column public."strategy_blocks"."executive_sponsor" is 'Executive sponsor for this item (Priorities layer)';
comment on column public."strategy_blocks"."target_year" is 'Target year for this item (Priorities layer), e.g. 2026';
comment on column public."strategy_blocks"."start_date" is 'Start date for this item';
comment on column public."strategy_blocks"."end_date" is 'End date for this item';
comment on column public."strategy_blocks"."due_date" is 'Due date for this item';
comment on column public."strategy_blocks"."progress" is 'Progress percentage 0-100. Auto-calculated from completed tasks.';
comment on column public."strategy_blocks"."priority" is 'Priority of the item: High, Medium, or Low. Empty until the user selects one.';
comment on column public."strategy_blocks"."custom_fields" is 'Values for this layer''s custom columns configured in the Strategy Customiser, keyed by custom column id';
comment on column public."strategy_blocks"."tracking_config" is 'Per-record tracking and monitoring configuration (Projects and Measures layers)';
comment on column public."strategy_blocks"."reporting_frequency" is 'Reporting frequency for count tracking: Monthly, Quarterly, Biannually, Annually, Every or Ad Hoc.';
comment on column public."strategy_blocks"."reporting_interval_value" is 'Custom reporting interval value, used only when reporting_frequency is ''Every''';
comment on column public."strategy_blocks"."reporting_interval_unit" is 'one of: Months | Years — Custom reporting interval unit, used only when reporting_frequency is ''Every''';
comment on column public."strategy_blocks"."reporting_period_start" is 'Reporting start date for count tracking. Reporting periods always follow the Financial Year (1 July - 30 June).';
comment on column public."strategy_blocks"."last_updated" is 'Date this measure was last updated';
comment on column public."strategy_blocks"."location_reporting_enabled" is 'Whether location based reporting is enabled for this measure''s reporting table';
comment on column public."strategy_blocks"."reporting_breakdown" is 'Reporting layout when location reporting is enabled: ''period'' or ''location''';
comment on column public."strategy_blocks"."reporting_locations" is 'Managed locations available in this block''s reporting table';
comment on column public."strategy_blocks"."report_columns" is 'Per-row reporting table column configuration';
comment on column public."strategy_blocks"."task_columns" is 'Per-record task table column configuration';
comment on column public."strategy_blocks"."outcomes" is 'Success outcomes for this item (Priorities layer)';
comment on column public."strategy_blocks"."contributes_to" is 'ID of the single other StrategyBlock this item contributes to (Connections). Empty when not linked.';
comment on column public."strategy_blocks"."health" is 'Health status of the item: On Track, Monitor, or Off Track. Empty until the user selects one.';
comment on column public."strategy_blocks"."status" is 'Delivery status of this item: Not Started, In Progress, Completed, On Hold, or Cancelled.';
comment on column public."strategy_blocks"."order_index" is 'Sort order within its parent';
create trigger "strategy_blocks_touch" before insert or update on public."strategy_blocks"
  for each row execute function public.b44_touch();
create index if not exists "strategy_blocks_created_date_idx" on public."strategy_blocks" (created_date desc);
