create index if not exists "strategy_blocks_parent_id_idx" on public."strategy_blocks" ("parent_id");
create index if not exists "strategy_blocks_level2_id_idx" on public."strategy_blocks" ("level2_id");
create index if not exists "strategy_blocks_custom_id_idx" on public."strategy_blocks" ("custom_id");

