-- WorkItem
create table if not exists public."work_items" (
  "id" text primary key default public.new_id(),
  "created_date" timestamptz not null default now(),
  "updated_date" timestamptz not null default now(),
  "created_by" text,
  "created_by_id" text,
  "is_sample" boolean not null default false,
  "_extra" jsonb not null default '{}'::jsonb,
  "work_plan_id" text,
  "item_id" text,
  "template_origin_id" text,
  "title" text,
  "description" text,
  "category" text,
  "owner" text,
  "frequency" text,
  "due_date" date,
  "priority" text,
  "status" text default 'Not Started',
  "register_status" text default 'active',
  "custom_fields" jsonb,
  "order_index" numeric default 0
);
comment on table public."work_items" is 'Base44 entity: WorkItem';
comment on column public."work_items"."work_plan_id" is 'REQUIRED — Parent WorkPlan ID';
comment on column public."work_items"."item_id" is 'Human-readable work item ID, e.g. ITEM-001';
comment on column public."work_items"."template_origin_id" is 'Stable identity of the work plan library item this work item was applied from. Used to prevent adding the same library item to the same work plan twice.';
comment on column public."work_items"."title" is 'REQUIRED — Work item title / name (required)';
comment on column public."work_items"."description" is 'Detailed description of the work item';
comment on column public."work_items"."category" is 'Work plan category value from work plan config';
comment on column public."work_items"."owner" is 'Person or role responsible for the work item';
comment on column public."work_items"."frequency" is 'How often this work item recurs (Monthly, Quarterly, Annually, Ad Hoc, One-off)';
comment on column public."work_items"."due_date" is 'The latest date this item should be completed by';
comment on column public."work_items"."priority" is 'Priority value from work plan config';
comment on column public."work_items"."status" is 'one of: Not Started | In Progress | Completed | On Hold | Cancelled — Work item status';
comment on column public."work_items"."register_status" is 'one of: active | completed | archived — Tab placement state for the work item';
comment on column public."work_items"."custom_fields" is 'JSON map of custom column id → value';
create trigger "work_items_touch" before insert or update on public."work_items"
  for each row execute function public.b44_touch();
create index if not exists "work_items_created_date_idx" on public."work_items" (created_date desc);
create index if not exists "work_items_work_plan_id_idx" on public."work_items" ("work_plan_id");
create index if not exists "work_items_item_id_idx" on public."work_items" ("item_id");
create index if not exists "work_items_template_origin_id_idx" on public."work_items" ("template_origin_id");

-- WorkPlan
create table if not exists public."work_plans" (
  "id" text primary key default public.new_id(),
  "created_date" timestamptz not null default now(),
  "updated_date" timestamptz not null default now(),
  "created_by" text,
  "created_by_id" text,
  "is_sample" boolean not null default false,
  "_extra" jsonb not null default '{}'::jsonb,
  "title" text,
  "description" text,
  "compliance_period_type" text default 'Financial Year',
  "financial_year_start" date,
  "financial_year_end" date,
  "status" text default 'active',
  "config" jsonb
);
comment on table public."work_plans" is 'Base44 entity: WorkPlan';
comment on column public."work_plans"."title" is 'REQUIRED — Work plan title, e.g. 2026-2027 Annual Board Work Plan';
comment on column public."work_plans"."description" is 'Optional description of the work plan';
comment on column public."work_plans"."compliance_period_type" is 'one of: Financial Year | Calendar Year — Which yearly cycle this work plan covers — Financial Year (1 July – 30 June) or Calendar Year (1 Jan – 31 Dec)';
comment on column public."work_plans"."financial_year_start" is 'Start date of the reporting period this work plan covers (1 July for FY, 1 Jan for calendar year)';
comment on column public."work_plans"."financial_year_end" is 'End date of the reporting period this work plan covers (30 June for FY, 31 Dec for calendar year)';
comment on column public."work_plans"."status" is 'one of: active | archived — Work plan lifecycle status — controls which tab (Active/Archived) it appears under';
comment on column public."work_plans"."config" is 'Work plan level configuration: field definitions, column order, etc.';
create trigger "work_plans_touch" before insert or update on public."work_plans"
  for each row execute function public.b44_touch();
create index if not exists "work_plans_created_date_idx" on public."work_plans" (created_date desc);

