-- WorkforceCredential
create table if not exists public."workforce_credentials" (
  "id" text primary key default public.new_id(),
  "created_date" timestamptz not null default now(),
  "updated_date" timestamptz not null default now(),
  "created_by" text,
  "created_by_id" text,
  "is_sample" boolean not null default false,
  "_extra" jsonb not null default '{}'::jsonb,
  "register_id" text,
  "person_id" text,
  "credential_name" text,
  "reference_number" text,
  "jurisdiction" text,
  "no_expiry" boolean default false,
  "expiry_date" date,
  "verification_status" text default 'Pending',
  "verified_date" date,
  "restricted" boolean default false,
  "note" text,
  "issue_date" date,
  "verified_by" text,
  "status" text default 'Active',
  "archived_with_person" boolean default false
);
comment on table public."workforce_credentials" is 'Base44 entity: WorkforceCredential';
comment on column public."workforce_credentials"."register_id" is 'REQUIRED';
comment on column public."workforce_credentials"."person_id" is 'REQUIRED — Parent WorkforcePerson ID';
comment on column public."workforce_credentials"."credential_name" is 'REQUIRED — Credential type, e.g. National Police Check';
comment on column public."workforce_credentials"."reference_number" is 'Licence / certificate number (shown masked)';
comment on column public."workforce_credentials"."jurisdiction" is 'e.g. National or State/Territory';
comment on column public."workforce_credentials"."verification_status" is 'one of: Verified | Pending | Exempted';
comment on column public."workforce_credentials"."verified_date" is 'Date verified; never in the future';
comment on column public."workforce_credentials"."restricted" is 'Sensitive record, reference hidden';
comment on column public."workforce_credentials"."status" is 'one of: Active | Archived — Credential lifecycle status. Validity (Current/Expired) is always derived from the expiry date.';
comment on column public."workforce_credentials"."archived_with_person" is 'True when this credential was archived by archiving its person; restoring the person restores only these.';
create trigger "workforce_credentials_touch" before insert or update on public."workforce_credentials"
  for each row execute function public.b44_touch();
create index if not exists "workforce_credentials_created_date_idx" on public."workforce_credentials" (created_date desc);
create index if not exists "workforce_credentials_register_id_idx" on public."workforce_credentials" ("register_id");
create index if not exists "workforce_credentials_person_id_idx" on public."workforce_credentials" ("person_id");

